import{_ as a,o as e,c as d,a3 as r}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"测试投入与风险覆盖","description":"","frontmatter":{"title":"测试投入与风险覆盖","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/quality/testing-strategy.md","filePath":"frontend/decisions/quality/testing-strategy.md","lastUpdated":1785589115000}'),i={name:"frontend/decisions/quality/testing-strategy.md"};function l(o,t,h,n,s,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="测试投入与风险覆盖" tabindex="-1">测试投入与风险覆盖 <a class="header-anchor" href="#测试投入与风险覆盖" aria-label="Permalink to &quot;测试投入与风险覆盖&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>测试投入的目标不是最大化用例数或覆盖率，而是在可接受成本内尽早发现最可能造成业务损失的错误。单元、组件、契约、端到端、视觉和生产监控提供不同证据，不能用一种测试层覆盖所有风险。</p><p>各层具体实践参见<a href="/frontend/guide/engineering/quality/testing-strategy">测试策略与可测试性</a>。本章只讨论如何依据风险分配投入和设置停止条件。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>统一要求“80% 覆盖率”会让简单函数得到大量测试，而支付、权限和跨服务契约仍可能缺乏保护。反过来只做 E2E，会得到慢、脆弱且难定位的反馈。</p><p>投入决策应以关键用户旅程和失败模式为单位，先估计影响和发生概率，再选择最便宜且足以发现该错误的证据层。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-不能妥协的风险" tabindex="-1">2.1 不能妥协的风险 <a class="header-anchor" href="#_2-1-不能妥协的风险" aria-label="Permalink to &quot;2.1 不能妥协的风险&quot;">​</a></h3><ul><li>身份、权限、金额、隐私和审计路径必须有自动化验证；</li><li>关键交易在发布前有跨边界证据，不能只验证前端函数；</li><li>无障碍、浏览器基线和服务端契约满足组织要求；</li><li>测试数据不得泄漏生产敏感信息；</li><li>不稳定测试不能被长期忽略，必须修复、隔离并有负责人。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>对每个风险评估业务影响、发生概率、可检测性、变更频率和恢复成本；对测试层评估反馈速度、环境真实性、定位能力、维护成本和误报率。</p><p>覆盖率可以发现未执行代码，但不能证明断言有效，也不能说明关键旅程被覆盖。</p><h2 id="_3-候选证据层" tabindex="-1">3. 候选证据层 <a class="header-anchor" href="#_3-候选证据层" aria-label="Permalink to &quot;3. 候选证据层&quot;">​</a></h2><h3 id="_3-1-静态检查与单元测试" tabindex="-1">3.1 静态检查与单元测试 <a class="header-anchor" href="#_3-1-静态检查与单元测试" aria-label="Permalink to &quot;3.1 静态检查与单元测试&quot;">​</a></h3><p>适合类型、纯规则、边界计算和大量组合，反馈快且定位清楚。无法证明组件、浏览器和服务端真正集成。</p><h3 id="_3-2-组件与视觉测试" tabindex="-1">3.2 组件与视觉测试 <a class="header-anchor" href="#_3-2-组件与视觉测试" aria-label="Permalink to &quot;3.2 组件与视觉测试&quot;">​</a></h3><p>适合交互状态、表单错误、键盘和视觉回归。比完整 E2E 更容易控制数据，但需要接近真实浏览器和设计基线。</p><h3 id="_3-3-接口与契约测试" tabindex="-1">3.3 接口与契约测试 <a class="header-anchor" href="#_3-3-接口与契约测试" aria-label="Permalink to &quot;3.3 接口与契约测试&quot;">​</a></h3><p>验证客户端与服务端对字段、错误、兼容和权限的共同理解。适合独立发布团队，不能替代真实环境中的路由、Cookie 和网关验证。</p><h3 id="_3-4-集成与端到端测试" tabindex="-1">3.4 集成与端到端测试 <a class="header-anchor" href="#_3-4-集成与端到端测试" aria-label="Permalink to &quot;3.4 集成与端到端测试&quot;">​</a></h3><p>覆盖用户旅程、部署配置和多个系统连接，最接近真实体验。执行慢、定位成本高，应聚焦高价值旅程和少量代表性分支。</p><h3 id="_3-5-人工探索与生产验证" tabindex="-1">3.5 人工探索与生产验证 <a class="header-anchor" href="#_3-5-人工探索与生产验证" aria-label="Permalink to &quot;3.5 人工探索与生产验证&quot;">​</a></h3><p>人工探索擅长发现未预期体验问题，灰度、监控和合成检查验证真实环境。它们是风险覆盖的一部分，但不能把已知可自动验证的回归长期留给人工或用户发现。</p><h2 id="_4-风险与测试层对比" tabindex="-1">4. 风险与测试层对比 <a class="header-anchor" href="#_4-风险与测试层对比" aria-label="Permalink to &quot;4. 风险与测试层对比&quot;">​</a></h2><p>案例是电商结算与商品目录：</p><table tabindex="0"><thead><tr><th>风险</th><th>影响/概率</th><th>首选证据</th><th>补充证据</th></tr></thead><tbody><tr><td>金额舍入错误</td><td>高/中</td><td>单元属性测试</td><td>结算 E2E</td></tr><tr><td>无权限用户提交订单</td><td>高/低</td><td>服务端授权测试、契约测试</td><td>真实环境 E2E</td></tr><tr><td>优惠字段不兼容</td><td>高/中</td><td>消费者契约</td><td>灰度错误监控</td></tr><tr><td>地址表单键盘不可用</td><td>中/中</td><td>组件浏览器测试</td><td>手工读屏抽查</td></tr><tr><td>商品卡片 1px 偏差</td><td>低/中</td><td>关键视口视觉回归</td><td>设计抽查</td></tr><tr><td>第三方支付回调失败</td><td>高/低</td><td>Sandbox 集成测试</td><td>合成监控与告警</td></tr></tbody></table><p>矩阵不会要求所有风险拥有相同数量的用例，而是确保高影响风险至少有一条发布前证据和一条生产恢复信号。</p><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>团队每迭代可投入约 25% 工程容量到质量活动。推荐分配原则而非固定永久比例：</p><ul><li>领域规则和状态转换随代码完成单元测试；</li><li>所有共享交互组件建立组件与无障碍测试；</li><li>订单、优惠和支付 API 使用消费者契约；</li><li>只保留登录、加购、结算、支付结果和退款五条核心 E2E，数据分支在更低层覆盖；</li><li>高变更营销页面做少量视觉回归，不阻塞低风险文案；</li><li>上线后以支付成功率、前端错误和合成结算作为最后证据。</li></ul><p>若 E2E 等待超过 15 分钟，优先下沉重复分支或拆并行，不通过删除关键旅程维持速度。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>风险驱动策略把高成本环境留给真正跨边界问题，反馈更快且定位清楚。代价是团队必须维护风险清单、测试所有者和生产指标，不能只靠一张覆盖率报表管理。</p><p>低风险视觉细节可能不在每次发布前完全自动验证，这是被明确接受的风险；高影响支付和权限则用多层证据覆盖。</p><p>退出某种工具不应改变风险契约。用例名称、Fixture 和断言应表达业务行为，避免全部绑定工具内部 API。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>不要把行覆盖率作为唯一发布门禁。</li><li>不要在 E2E 中穷举所有输入组合。</li><li>不要用大量 Mock 后声称已经验证前后端契约。</li><li>不稳定测试不能通过无限重试变成绿色。</li><li>生产监控不能替代发布前对高风险路径的验证。</li><li>低风险代码也需要基本静态检查，但不应获得与支付相同投入。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>结算和目录团队如何分配有限测试容量</td></tr><tr><td>硬约束</td><td>支付、权限、隐私和关键无障碍自动覆盖；关键旅程发布前验证</td></tr><tr><td>候选</td><td>统一覆盖率、E2E 为主、风险分层组合</td></tr><tr><td>决定</td><td>风险分层组合，五条核心 E2E</td></tr><tr><td>证据</td><td>过去 12 个月缺陷、故障影响、变更频率、各层执行与维护时间</td></tr><tr><td>接受风险</td><td>低风险文案和细微视觉不阻塞全部发布</td></tr><tr><td>质量预算</td><td>每迭代约 25%，按风险变化调整而非按层固定</td></tr><tr><td>监控指标</td><td>逃逸缺陷、反馈 P75、不稳定率、关键旅程覆盖、修复时间</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>高严重度逃逸缺陷出现、E2E 反馈超过 15 分钟、不稳定率超过 2%、某领域变更频率显著增加，或测试维护超过迭代容量 35% 时复查。复查应调整风险与证据映射，而不是简单提高或降低统一覆盖率。</p>',42)])])}const _=a(i,[["render",l]]);export{p as __pageData,_ as default};
